package com.kitchenos.connect.ui;
import android.app.Activity;
import android.graphics.Typeface;
import android.graphics.drawable.GradientDrawable;
import android.os.Handler;
import android.view.*;
import android.view.inputmethod.*;
import android.widget.*;
import java.util.*;

/** German keyboard scoped to one editor in this app. No system input interception or text storage. */
public final class ApplianceKeyboard extends LinearLayout {
    private final Activity activity;private final EditText editor;private final Runnable hide;private final EditorInfo info=new EditorInfo();
    private final LinearLayout surface=this;private final ArrayList<Button> keys=new ArrayList<>();private boolean shifted,numbers,umlauts;private int bg,key,ink,accent=0xffee6542;private final Handler main=new Handler();private final RotaryController knob;
    public ApplianceKeyboard(Activity activity,EditText editor,Runnable hide){super(activity);this.activity=activity;this.editor=editor;this.hide=hide;setOrientation(VERTICAL);knob=new RotaryController(activity,hide);editor.setTag(com.kitchenos.connect.R.id.appliance_keyboard,Boolean.TRUE);editor.setShowSoftInputOnFocus(false);info.imeOptions=editor.getImeOptions();drawKeys();}
    private int dp(int value){return Math.round(value*getResources().getDisplayMetrics().density);}
    public boolean dispatch(KeyEvent event){return knob.dispatch(event);}
    @Override protected void onDetachedFromWindow(){main.removeCallbacksAndMessages(null);super.onDetachedFromWindow();}
    private void drawKeys(){if(surface==null)return;boolean dark=!activity.getSharedPreferences("appearance",0).getString("theme","dark").equals("light");bg=dark?0xff171918:0xfff0f1ed;key=dark?0xff303632:0xffffffff;ink=dark?0xfff2f3ee:0xff171716;surface.removeAllViews();keys.clear();knob.reset();surface.setBackgroundColor(bg);surface.setPadding(dp(8),dp(8),dp(8),dp(12));
        String[] rows=numbers?new String[]{"1 2 3 4 5 6 7 8 9 0","@ # € _ & - + ( ) /","* \" ' : ; ! ?"}:new String[]{"q w e r t z u i o p","a s d f g h j k l","y x c v b n m"};
        for(int i=0;i<rows.length;i++){LinearLayout line=row();if(i==2)glyph(line,"shift","Großschreibung",1.2f,()->{shifted=!shifted;drawKeys();});for(String letter:rows[i].split(" ")){final String value=shifted?letter.toUpperCase(Locale.GERMAN):letter;Button letterKey=add(line,value,1,()->commit(value));String alternate=letter.equals("a")?"ä":letter.equals("o")?"ö":letter.equals("u")?"ü":letter.equals("s")?"ß":null;if(alternate!=null){final String longValue=shifted?alternate.toUpperCase(Locale.GERMAN):alternate;letterKey.setContentDescription(value+", halten für "+longValue);letterKey.setOnLongClickListener(v->{commit(longValue);return true;});}}if(i==2){Button erase=glyph(line,"backspace","Zeichen löschen",1.2f,this::erase);erase.setContentDescription("Zeichen löschen");final Runnable repeat=new Runnable(){public void run(){erase();main.postDelayed(this,80);}};erase.setOnTouchListener((v,e)->{if(e.getAction()==MotionEvent.ACTION_DOWN){erase();main.postDelayed(repeat,450);return true;}if(e.getAction()==MotionEvent.ACTION_UP||e.getAction()==MotionEvent.ACTION_CANCEL){main.removeCallbacks(repeat);return true;}return true;});}}
        LinearLayout last=row();add(last,numbers?"ABC":"123",1.3f,()->{numbers=!numbers;drawKeys();});add(last,",",.8f,()->commit(","));add(last,"Leerzeichen",3.4f,()->commit(" "));add(last,".",.8f,()->commit("."));int action=info==null?0:info.imeOptions&EditorInfo.IME_MASK_ACTION;add(last,action==EditorInfo.IME_ACTION_SEND?"Senden":action==EditorInfo.IME_ACTION_DONE?"Fertig":action==EditorInfo.IME_ACTION_SEARCH?"Suchen":"↵",2,()->{InputConnection connection=editor.onCreateInputConnection(new EditorInfo());if(connection==null)return;if(action!=EditorInfo.IME_ACTION_NONE&&action!=EditorInfo.IME_ACTION_UNSPECIFIED)connection.performEditorAction(action);else connection.commitText("\n",1);});
    }
    private LinearLayout row(){LinearLayout row=new LinearLayout(activity);row.setBaselineAligned(false);surface.addView(row,new LinearLayout.LayoutParams(-1,-2));return row;}
    private Button add(LinearLayout row,String label,float weight,Runnable action){Button button=new Button(activity);button.setAllCaps(false);button.setText(label);button.setTextColor(ink);button.setTextSize(label.length()>3?21:27);button.setGravity(Gravity.CENTER);button.setIncludeFontPadding(false);button.setMinHeight(0);button.setMinimumHeight(0);button.setTypeface(null,Typeface.NORMAL);button.setStateListAnimator(null);button.setMinWidth(0);button.setMinimumWidth(0);button.setPadding(0,0,0,0);button.setOnClickListener(v->action.run());background(button,false);LinearLayout.LayoutParams params=new LinearLayout.LayoutParams(0,dp(96),weight);params.setMargins(dp(2),dp(2),dp(2),dp(2));row.addView(button,params);keys.add(button);knob.add(button);return button;}
    private Button glyph(LinearLayout row,String id,String label,float weight,Runnable action){Button button=new Button(activity){@Override protected void onDraw(android.graphics.Canvas canvas){InterfaceIcon icon=new InterfaceIcon(id,ink);int size=dp(30),x=(getWidth()-size)/2,y=(getHeight()-size)/2;icon.setBounds(x,y,x+size,y+size);icon.draw(canvas);}};button.setContentDescription(label);button.setMinWidth(0);button.setMinimumWidth(0);button.setMinHeight(0);button.setMinimumHeight(0);button.setPadding(0,0,0,0);button.setStateListAnimator(null);button.setOnClickListener(v->action.run());background(button,false);LinearLayout.LayoutParams params=new LinearLayout.LayoutParams(0,dp(96),weight);params.setMargins(dp(2),dp(2),dp(2),dp(2));row.addView(button,params);keys.add(button);knob.add(button);return button;}
    private void background(Button button,boolean selected){GradientDrawable shape=new GradientDrawable();shape.setColor(selected?accent:key);shape.setCornerRadius(dp(12));android.graphics.drawable.StateListDrawable states=new android.graphics.drawable.StateListDrawable();GradientDrawable focus=new GradientDrawable();focus.setColor(accent);focus.setCornerRadius(dp(12));states.addState(new int[]{android.R.attr.state_selected},focus);states.addState(new int[]{},shape);button.setBackground(states);button.setTextColor(ink);}
    private void commit(String value){InputConnection connection=editor.onCreateInputConnection(new EditorInfo());if(connection!=null)connection.commitText(value,1);if(shifted){shifted=false;drawKeys();}}
    private void erase(){InputConnection connection=editor.onCreateInputConnection(new EditorInfo());if(connection==null)return;CharSequence selected=connection.getSelectedText(0);if(selected!=null&&selected.length()>0)connection.commitText("",1);else connection.deleteSurroundingTextInCodePoints(1,0);}
}
